    pro_save_limit_heading: 'இலவச திட்ட வரம்பு முடிந்தது (20 புகைப்படங்கள்)',
    pro_save_limit_desc: 'நீங்கள் லோடிங் டாக்கில் வரம்பற்ற புகைப்படங்களைப் பதிவேற்றலாம். எனினும், இலவச திட்டத்தில் கேலரி மற்றும் ஆல்பங்களில் அதிகபட்சம் 20 புகைப்படங்களை மட்டுமே சேமிக்க முடியும். வரம்பற்ற சேமிப்பிற்கு PicShelf Proவிற்கு மேம்படுத்தவும்!',
