    pro_save_limit_desc: 'ലോഡിംഗ് ഡോക്കിലേക്ക് നിങ്ങൾക്ക് എത്ര ഫോട്ടോകൾ വേണമെങ്കിലും അപ്‌ലോഡ് ചെയ്യാം. എന്നാൽ സൗജന്യ പ്ലാനിൽ ഗാലറിയിലും ആൽബങ്ങളിലും പരമാവധി 20 ഫോട്ടോകൾ മാത്രമേ സൂക്ഷിക്കാൻ കഴിയൂ. പരിധിയില്ലാതെ സംരക്ഷിക്കാൻ PicShelf Proയിലേക്ക് അപ്‌ഗ്രേഡ് ചെയ്യുക!',
